package docker

import (
	"slices"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/engine"
)

// OC-07: a test whose result depends on the engine runs once per declared
// engine, through forEachEngine. These tests pin the helper itself. The seams
// it drives (the runner, the current engine) are global, so none of them calls
// t.Parallel.
//
// Expected helper, defined next to stub and useEngine in exec_test.go:
//
//	func forEachEngine(t *testing.T, fn func(t *testing.T, shape engine.Shape))
//
// For every name in engine.Names() it runs fn in a subtest named after the
// engine, with useEngine already applied, and puts the original engine back
// when the subtests are over.

func TestForEachEngineRunsOncePerDeclaredEngine(t *testing.T) {
	// A sentinel that is neither declared shape, so "restored" cannot be
	// mistaken for "left on docker".
	sentinel := engine.Shape{Name: engine.Docker, Binary: "oc07-sentinel"}
	previous := engine.Current()
	engine.SetCurrent(sentinel)
	t.Cleanup(func() { engine.SetCurrent(previous) })

	var visited, current, subtests []string
	t.Run("inner", func(t *testing.T) {
		forEachEngine(t, func(t *testing.T, shape engine.Shape) {
			visited = append(visited, shape.Name)
			current = append(current, engine.Current().Name)
			subtests = append(subtests, t.Name())
		})
	})

	if want := engine.Names(); !slices.Equal(visited, want) {
		t.Errorf("forEachEngine visited %v, want once per declared engine %v", visited, want)
	}
	// fn must see the engine it was handed already pinned, or an argv built
	// from engine.Current() would belong to the previous iteration.
	if !slices.Equal(current, visited) {
		t.Errorf("engine.Current() inside fn = %v, want %v", current, visited)
	}
	for i, name := range visited {
		if !strings.HasSuffix(subtests[i], "/"+name) {
			t.Errorf("subtest %q is not named after the engine %q", subtests[i], name)
		}
	}
	if got := engine.Current(); got != sentinel {
		t.Errorf("engine.Current() after forEachEngine = %+v, want the engine it found, %+v", got, sentinel)
	}
}

// The shape handed to fn is the declared one, templates included: it is what a
// test builds its expected argv from.
func TestForEachEngineHandsOverTheDeclaredShape(t *testing.T) {
	forEachEngine(t, func(t *testing.T, shape engine.Shape) {
		if want := engine.ShapeFor(shape.Name); shape != want {
			t.Errorf("shape = %+v, want engine.ShapeFor(%q) = %+v", shape, shape.Name, want)
		}
	})
}

// OC-07 criterion 4: an engine added to the configuration must fail a test
// until forEachEngine runs it. The configuration is the authority on what can
// be selected, so the comparison starts there rather than from engine.Names().
//
// It sits beside TestEveryConfiguredEngineHasAShape (internal/engine), which
// holds config and shapes in step; this one holds the helper to the same list.
func TestForEachEngineCoversEveryConfiguredEngine(t *testing.T) {
	var visited []string
	forEachEngine(t, func(t *testing.T, shape engine.Shape) {
		visited = append(visited, shape.Name)
	})

	for _, name := range config.ContainerEngines() {
		if name == config.EngineAuto {
			// auto is a resolution strategy, not an engine.
			continue
		}
		if !slices.Contains(visited, name) {
			t.Errorf("config offers %q but forEachEngine never runs it", name)
		}
	}
	for _, name := range visited {
		if !slices.Contains(config.ContainerEngines(), name) {
			t.Errorf("forEachEngine runs %q but the configuration never offers it", name)
		}
	}
}
package docker

import (
	"errors"
	"fmt"
	"slices"
	"strings"
	"testing"
)

// OC-07 criterion 2: a stub that is told which argv to expect fails the test
// on any other one, and says which.
//
// Expected additions to exec_test.go:
//
//	// reply is one invocation a strict stub accepts, matched on the whole argv.
//	type reply struct {
//		argv []string
//		out  string
//		err  error
//	}
//
//	// reporter is the part of testing.TB a strict stub fails through; a test of
//	// the stub itself passes a recorder instead of the real *testing.T.
//	type reporter interface {
//		Helper()
//		Errorf(format string, args ...any)
//	}
//
//	// stubRunner gains two fields: `replies []reply` and `report reporter`.
//	// With a non-nil report the stub is strict: Run and Build fail through
//	// report.Errorf for an argv no reply names, and Run then returns
//	// errUnexpectedArgv. Without one it behaves as it always did, keyed by
//	// subcommand (the tests not yet migrated).
//	var errUnexpectedArgv = errors.New("unexpected argv")
//
//	// stubStrict is stub for a strict stubRunner reporting through t.
//	func stubStrict(t testing.TB, replies ...reply) *stubRunner
//
// The failure message contains fmt.Sprintf("%q", argv), so a reader sees the
// exact words the code under test passed.

// recorder stands in for *testing.T so the failure can be observed instead of
// failing the run.
type recorder struct{ msgs []string }

func (r *recorder) Helper() {}
func (r *recorder) Errorf(format string, args ...any) {
	r.msgs = append(r.msgs, fmt.Sprintf(format, args...))
}

func TestStrictStubAcceptsOnlyTheDeclaredArgv(t *testing.T) {
	boom := errors.New("exit status 1")
	declared := []reply{
		{argv: []string{"volume", "ls", "--format", "{{.Name}}"}, out: "pgdata\n"},
		{argv: []string{"volume", "rm", "pgdata"}, err: boom},
	}

	tests := []struct {
		name    string
		argv    []string
		wantOut string
		wantErr func(error) bool
		wantMsg string // substring of the one failure, "" for none
	}{
		{
			name:    "a declared argv gets its canned output",
			argv:    []string{"volume", "ls", "--format", "{{.Name}}"},
			wantOut: "pgdata\n",
			wantErr: func(err error) bool { return err == nil },
		},
		{
			name:    "a declared argv gets its canned error",
			argv:    []string{"volume", "rm", "pgdata"},
			wantErr: func(err error) bool { return errors.Is(err, boom) },
		},
		{
			name:    "an undeclared subcommand fails with its argv",
			argv:    []string{"volume", "prune", "--force"},
			wantErr: func(err error) bool { return errors.Is(err, errUnexpectedArgv) },
			wantMsg: `["volume" "prune" "--force"]`,
		},
		{
			// The old stub keyed on the first word, so this passed whatever
			// template the code asked for. That is the hole OC-07 closes.
			name:    "the right subcommand with another template fails",
			argv:    []string{"volume", "ls", "--format", "{{.Name}}\t{{.Driver}}"},
			wantErr: func(err error) bool { return errors.Is(err, errUnexpectedArgv) },
			wantMsg: `["volume" "ls" "--format" "{{.Name}}\t{{.Driver}}"]`,
		},
		{
			name:    "a declared argv with an extra argument fails",
			argv:    []string{"volume", "rm", "pgdata", "cache"},
			wantErr: func(err error) bool { return errors.Is(err, errUnexpectedArgv) },
			wantMsg: `["volume" "rm" "pgdata" "cache"]`,
		},
		{
			name:    "a bare declared prefix fails",
			argv:    []string{"volume"},
			wantErr: func(err error) bool { return errors.Is(err, errUnexpectedArgv) },
			wantMsg: `["volume"]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rec := &recorder{}
			s := &stubRunner{replies: declared, report: rec}

			out, err := s.Run(dockerCmd{Args: tt.argv})

			if !tt.wantErr(err) {
				t.Errorf("Run(%q) error = %v", tt.argv, err)
			}
			if string(out) != tt.wantOut {
				t.Errorf("Run(%q) output = %q, want %q", tt.argv, out, tt.wantOut)
			}
			switch {
			case tt.wantMsg == "" && len(rec.msgs) != 0:
				t.Errorf("a declared argv was reported: %v", rec.msgs)
			case tt.wantMsg != "" && len(rec.msgs) != 1:
				t.Fatalf("reports = %v, want exactly one naming the argv", rec.msgs)
			case tt.wantMsg != "" && !strings.Contains(rec.msgs[0], tt.wantMsg):
				t.Errorf("report = %q, want it to contain the argv %s", rec.msgs[0], tt.wantMsg)
			}
			// A rejected call is still on the record, so a failing test can be
			// read from s.calls and lastArgs as well as from the message.
			if !slices.Equal(s.lastArgs(), tt.argv) {
				t.Errorf("lastArgs() = %q, want the call recorded as %q", s.lastArgs(), tt.argv)
			}
		})
	}
}

// Build is the other way in: the launch and exec paths hand the command to the
// terminal instead of running it, and must not slip past the check.
func TestStrictStubChecksBuildToo(t *testing.T) {
	rec := &recorder{}
	s := &stubRunner{
		replies: []reply{{argv: []string{"exec", "-it", "abc", "sh"}}},
		report:  rec,
	}

	s.Build("exec", "-it", "abc", "sh")
	if len(rec.msgs) != 0 {
		t.Errorf("a declared Build was reported: %v", rec.msgs)
	}

	s.Build("exec", "-it", "abc", "bash")
	if len(rec.msgs) != 1 || !strings.Contains(rec.msgs[0], `["exec" "-it" "abc" "bash"]`) {
		t.Errorf("reports = %v, want one naming the undeclared Build argv", rec.msgs)
	}
}

// A stub with no reporter is the one every test not yet migrated builds: keyed
// by subcommand, answering anything. Strictness is opted into, so the migration
// can go test by test.
func TestAStubWithoutAReporterStaysKeyedBySubcommand(t *testing.T) {
	s := &stubRunner{output: map[string][]byte{"volume": []byte("pgdata\n")}}

	out, err := s.Run(dockerCmd{Args: []string{"volume", "anything", "at", "all"}})

	if err != nil || string(out) != "pgdata\n" {
		t.Errorf("Run() = %q, %v, want the subcommand's canned output", out, err)
	}
}

// End to end: strictness exists to catch a template that is wrong for the
// engine. Here podman is asked for `network ls` while the stub only knows
// docker's template, and the test must fail naming that argv.
func TestStrictStubCatchesATemplateOfTheWrongEngine(t *testing.T) {
	rec := &recorder{}
	s := &stubRunner{
		replies: []reply{{argv: []string{"network", "ls", "--format", dockerNetworkLS}}},
		report:  rec,
	}
	stub(t, s)
	useEngine(t, "podman")

	_, _ = ListNetworks()

	if len(rec.msgs) != 1 {
		t.Fatalf("reports = %v, want one for podman's own template", rec.msgs)
	}
	if !strings.Contains(rec.msgs[0], `"{{.ID}}\t{{.Name}}\t{{.Driver}}\t\t{{.Created}}"`) {
		t.Errorf("report = %q, want it to show podman's NetworkLS template", rec.msgs[0])
	}
}

// dockerNetworkLS is written out rather than read from the shape, so that a
// change to docker's template is a visible edit here too.
const dockerNetworkLS = "{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}\t{{.CreatedAt}}"
